//! Rules behind the lobby options and the battlefield leftovers (generated by
//! `tools/gen_rules.py` like the rest of `rules.json`): crates and the crate
//! spawner (crates.rs), husks (husks.rs), the survivors of a sold structure
//! (sell.rs), primary buildings (primary.rs), short game, kill bounties,
//! handicaps and the time limit (gamerules.rs), starting units, and the
//! warheads that change no health (smudges.rs).
//!
//! Actor names in these rules are kept as OpenRA spells them. Types WebRA does
//! not have (yet) are left out when the rules load, so a crate squad or the
//! crew of a sold structure fills in as more actors are added.

use crate::rules::{Kind, Rules};
use serde::Deserialize;

/// OpenRA OwnerLostAction: what happens to an actor when its owner loses.
#[derive(Deserialize, Clone, Copy, PartialEq, Eq, Debug)]
#[serde(rename_all = "snake_case")]
pub enum OwnerLost {
    Kill,
    Dispose,
    /// To the neutral player (husks, walls).
    ChangeOwner,
}

#[derive(Deserialize, Clone, Debug)]
pub(crate) struct RawSellSurvivors {
    actor_types: Vec<String>,
    guaranteed: Vec<String>,
    value_percent: i32,
    min_hp_percent: i32,
    factions: Vec<String>,
}

/// OpenRA SpawnActorsOnSell: the crew that leaves a sold structure (sell.rs).
#[derive(Clone, Debug)]
pub struct SellSurvivors {
    pub actor_types: Vec<usize>,
    pub guaranteed: Vec<usize>,
    pub value_percent: i32,
    pub min_hp_percent: i32,
    /// Faction indices; empty: every faction.
    pub factions: Vec<usize>,
}

#[derive(Deserialize, Clone, Debug)]
pub(crate) struct RawHuskCapture {
    types: Vec<String>,
    transform_into: String,
    force_health_percent: i32,
}

/// Taking a husk back: OpenRA Capturable + TransformOnCapture (and
/// InfiltrateForTransform), for the capturing infantry.
#[derive(Clone, Debug)]
pub struct HuskCapture {
    /// Capture types (`husk`) or infiltration types (`Husk`) that apply.
    pub types: Vec<String>,
    /// Actor type the husk turns into.
    pub transform_into: usize,
    /// Health of the restored actor in percent of its maximum (0: the husk's ratio).
    pub force_health_percent: i32,
}

#[derive(Deserialize, Clone, Debug)]
pub(crate) struct RawHusk {
    allowed_terrain: Vec<String>,
    crushes: Vec<String>,
    burn_step: i32,
    burn_delay: i32,
    burn_start_if_below: i32,
    force_fire_only: bool,
    radius: i32,
    capturable: Option<RawHuskCapture>,
    infiltrate: Option<RawHuskCapture>,
}

/// OpenRA ^Husk (husks.rs).
#[derive(Clone, Debug)]
pub struct HuskInfo {
    pub allowed_terrain: Vec<String>,
    /// Crush classes of the husk's locomotor: what it crushes where it lands.
    pub crushes_infantry: bool,
    pub crushes_mines: bool,
    pub crushes_crates: bool,
    /// ChangesHealth: hit points per step (negative: it burns), ticks per step,
    /// and the percent of health below which it acts.
    pub burn_step: i32,
    pub burn_delay: i32,
    pub burn_start_if_below: i32,
    /// Targetable only with force-fire (RequiresForceFire) and never auto-targeted.
    pub force_fire_only: bool,
    /// Hit radius (world units).
    pub radius: i32,
    pub capturable: Option<HuskCapture>,
    pub infiltrate: Option<HuskCapture>,
}

