/// One crate action (crates.rs). Fields that do not apply to the kind are 0 / empty.
#[derive(Clone, Debug)]
pub struct CrateAction {
    pub key: String,
    pub kind: CrateActionKind,
    pub shares: i32,
    /// Not before this tick (OpenRA TimeDelay).
    pub time_delay: i32,
    /// Prerequisite tokens the collector's owner must have.
    pub prerequisites: Vec<u16>,
    /// Collector types this action never happens for.
    pub excluded: Vec<usize>,
    /// crate-effects sequence and sound (presentation, client side).
    pub sequence: Option<String>,
    pub sound: Option<String>,
    pub notification: Option<String>,
    pub amount: i32,
    pub levels: i32,
    pub range: i32,
    pub max_extra: i32,
    pub weapon: Option<usize>,
    pub include_allies: bool,
    pub targets: u32,
    pub min_amount: i32,
    pub max_amount: i32,
    pub max_duplicate_value: i32,
    pub max_radius: i32,
    /// Faction indices; empty: every faction.
    pub factions: Vec<usize>,
    /// Actor types to give (only those WebRA has).
    pub units: Vec<usize>,
    pub no_base_shares: i32,
    pub condition: Option<String>,
    pub duration: i32,
}

