/// The kinds of warhead that change no health.
#[derive(Deserialize, Clone, Copy, PartialEq, Eq, Debug)]
#[serde(rename_all = "snake_case")]
pub enum EffectKind {
    /// LeaveSmudge: scorch marks and craters (presentation, smudges.rs).
    Smudge,
    /// DestroyResource: explosions clear ore and gems (gameplay).
    DestroyResource,
    /// CreateResource: an exploding ore truck spills ore (gameplay).
    CreateResource,
    /// ShakeScreen (presentation).
    Shake,
    /// FlashEffect: the nuke's white flash (presentation).
    Flash,
}

#[derive(Deserialize, Clone, Debug)]
pub(crate) struct RawWarheadEffect {
    kind: EffectKind,
    delay: i32,
    valid: u32,
    invalid: u32,
    size: Vec<i32>,
    #[serde(default)]
    smudge_types: Vec<String>,
    #[serde(default)]
    chance: i32,
    #[serde(default)]
    amount: i32,
    #[serde(default)]
    resource_types: Vec<String>,
    #[serde(default)]
    duration: i32,
    #[serde(default)]
    intensity: i32,
    #[serde(default)]
    multiplier: Vec<i32>,
    #[serde(default)]
    flash_type: String,
}

/// Resource kinds a warhead names.
pub const RESOURCE_ORE: u8 = 1;
pub const RESOURCE_GEMS: u8 = 2;

/// A warhead that changes no health (smudges.rs).
#[derive(Clone, Debug)]
pub struct WarheadEffect {
    pub kind: EffectKind,
    pub delay: i32,
    pub valid: u32,
    pub invalid: u32,
    /// Outer and inner radius of the affected cells (OpenRA Size).
    pub outer: i32,
    pub inner: i32,
    /// Smudge: bit 0 scorch, bit 1 crater.
    pub smudge_types: u8,
    pub chance: i32,
    /// DestroyResource: bales removed per cell (0: all).
    pub amount: i32,
    /// RESOURCE_* bits (DestroyResource: 0 means every type).
    pub resources: u8,
    pub duration: i32,
    pub intensity: i32,
    pub multiplier: (i32, i32),
    pub flash_type: String,
}

pub const SMUDGE_SCORCH: u8 = 1;
pub const SMUDGE_CRATER: u8 = 2;

