/// Lobby option fields of an actor.
#[derive(Clone, Debug, Default)]
pub struct ActorOptions {
    /// OpenRA MustBeDestroyed: None when the actor does not keep its owner in
    /// the game; else whether it also counts with the short game option
    /// (RequiredForShortGame).
    pub must_be_destroyed: Option<bool>,
    pub owner_lost: Option<OwnerLost>,
    /// GivesBounty: percent of the actor's value its killer gets (kill bounties option).
    pub gives_bounty: Option<i32>,
    /// ^PlayerHandicaps: the owner's handicap lowers its firepower and armour and slows production.
    pub handicaps: bool,
    /// SpawnActorOnDeath: the husk it leaves (husks.rs), or a crate (a
    /// Supply Truck's money crate, crates.rs).
    pub spawn_on_death: Option<usize>,
    /// HarvesterHuskModifier: the husk of a harvester at least this many percent full.
    pub full_husk: Option<(usize, i32)>,
    pub sell_survivors: Option<SellSurvivors>,
    /// PrimaryBuilding (primary.rs).
    pub primary_building: bool,
    /// ShakeOnDeath (duration, intensity): presentation only.
    pub shake_on_death: Option<(i32, i32)>,
    /// FireWarheadsOnDeath only with resources on board (`!no-ore`: ore trucks).
    pub death_needs_resources: bool,
    pub husk: Option<HuskInfo>,
    pub crate_info: Option<CrateInfo>,
}

/// Bounds of the values below (same spirit as `Rules::validate`).
const TIMER: i32 = 100_000;
const CELLS: i32 = 1024;

fn within(what: &str, v: i32, lo: i32, hi: i32) -> Result<(), String> {
    if v < lo || v > hi {
        return Err(format!("{what} must be between {lo} and {hi}, is {v}"));
    }
    Ok(())
}

fn count(what: &str, len: usize, max: usize) -> Result<(), String> {
    if len > max {
        return Err(format!("{what} may have at most {max} entries, has {len}"));
    }
    Ok(())
}

fn truncate(s: &str) -> String {
    s.chars().take(40).collect()
}

/// Ids to actor table indices, ignoring case; unknown names are left out.
fn known(ids: &[String], names: &[String]) -> Vec<usize> {
    names.iter().filter_map(|n| ids.iter().position(|i| i.eq_ignore_ascii_case(n))).collect()
}

fn factions_of(factions: &[String], names: &[String]) -> Vec<usize> {
    names.iter().filter_map(|n| factions.iter().position(|f| f == n)).collect()
}

/// Resolve the option fields of actor `id` (ids: every actor id in table order).
pub(crate) fn resolve_actor(
    id: &str,
    raw: RawActorOptions,
    ids: &[String],
    factions: &[String],
    intern: &mut dyn FnMut(&str) -> u16,
) -> Result<ActorOptions, String> {
    let n = |f: &str| format!("actors.{}.{f}", truncate(id));
    let index_of =
        |name: &str, what: &str| ids.iter().position(|i| i.eq_ignore_ascii_case(name)).ok_or_else(|| n(&format!("{what}: unknown actor")));
    let spawn_on_death = raw.spawn_on_death.as_deref().map(|s| index_of(s, "spawn_on_death")).transpose()?;
    let full_husk = match raw.full_husk {
        Some((a, t)) => Some((index_of(&a, "full_husk")?, t)),
        None => None,
    };
    let sell_survivors = raw.sell_survivors.map(|s| SellSurvivors {
        actor_types: known(ids, &s.actor_types),
        guaranteed: known(ids, &s.guaranteed),
        value_percent: s.value_percent,
        min_hp_percent: s.min_hp_percent,
        factions: factions_of(factions, &s.factions),
    });
    let capture = |c: Option<RawHuskCapture>, what: &str| -> Result<Option<HuskCapture>, String> {
        match c {
            None => Ok(None),
            Some(c) => Ok(Some(HuskCapture {
                types: c.types,
                transform_into: index_of(&c.transform_into, what)?,
                force_health_percent: c.force_health_percent,
            })),
        }
    };
    let husk = match raw.husk {
        None => None,
        Some(h) => Some(HuskInfo {
            crushes_infantry: h.crushes.iter().any(|c| c == "infantry"),
            crushes_mines: h.crushes.iter().any(|c| c == "mine"),
            crushes_crates: h.crushes.iter().any(|c| c == "crate"),
            allowed_terrain: h.allowed_terrain,
            burn_step: h.burn_step,
            burn_delay: h.burn_delay,
            burn_start_if_below: h.burn_start_if_below,
            force_fire_only: h.force_fire_only,
            radius: h.radius,
            capturable: capture(h.capturable, "husk.capturable.transform_into")?,
            infiltrate: capture(h.infiltrate, "husk.infiltrate.transform_into")?,
        }),
    };
    let crate_info = match raw.crate_info {
        None => None,
        Some(c) => {
            count(&n("crate.actions"), c.actions.len(), 64)?;
            let mut actions = Vec::new();
            for a in c.actions {
                actions.push(CrateAction {
                    prerequisites: a.prerequisites.iter().map(|p| intern(p.trim_start_matches('~'))).collect(),
                    excluded: known(ids, &a.excluded),
                    factions: factions_of(factions, &a.factions),
                    units: known(ids, &a.units),
                    key: a.key,
                    kind: a.kind,
                    shares: a.shares,
                    time_delay: a.time_delay,
                    sequence: a.sequence,
                    sound: a.sound,
                    notification: a.notification,
                    amount: a.amount,
                    levels: a.levels,
                    range: a.range,
                    max_extra: a.max_extra,
                    weapon: a.weapon,
                    include_allies: a.include_allies,
                    targets: a.targets,
                    min_amount: a.min_amount,
                    max_amount: a.max_amount,
                    max_duplicate_value: a.max_duplicate_value,
                    max_radius: a.max_radius,
                    no_base_shares: a.no_base_shares,
                    condition: a.condition,
                    duration: a.duration,
                });
            }
            Some(CrateInfo { duration: c.duration, terrain: c.terrain, crush_class: c.crush_class, actions })
        }
    };
    Ok(ActorOptions {
        must_be_destroyed: raw.must_be_destroyed,
        owner_lost: raw.owner_lost,
        gives_bounty: raw.gives_bounty,
        handicaps: raw.handicaps,
        spawn_on_death,
        full_husk,
        sell_survivors,
        primary_building: raw.primary_building,
        shake_on_death: raw.shake_on_death,
        death_needs_resources: raw.death_needs_resources,
        husk,
        crate_info,
    })
}

/// Resolve the world rules.
pub(crate) fn resolve_world(raw: RawWorldRules, ids: &[String], factions: &[String]) -> Result<WorldRules, String> {
    let c = raw.crates;
    let index_of = |name: &str, what: &str| {
        ids.iter().position(|i| i.eq_ignore_ascii_case(name)).ok_or_else(|| format!("world.{what}: unknown actor"))
    };
    let mut actors = Vec::new();
    for a in &c.actors {
        actors.push(index_of(a, "crates.actors")?);
    }
    let crates = CrateSpawnerInfo {
        minimum: c.minimum,
        maximum: c.maximum,
        spawn_interval: c.spawn_interval,
        initial_delay: c.initial_delay,
        water_chance: c.water_chance,
        quantized_facings: c.quantized_facings,
        cordon: c.cordon,
        delivery_aircraft: c.delivery_aircraft.as_deref().map(|d| index_of(d, "crates.delivery_aircraft")).transpose()?,
        actors,
        shares: c.shares,
        valid_ground: c.valid_ground,
        valid_water: c.valid_water,
    };
    let mut starting_units = Vec::new();
    for s in raw.starting_units {
        starting_units.push(StartingUnitsInfo {
            factions: factions_of(factions, &s.factions),
            base_actor: s.base_actor.as_deref().map(|b| index_of(b, "starting_units.base_actor")).transpose()?,
            support_actors: known(ids, &s.support_actors),
            class: s.class,
            inner_radius: s.inner_radius,
            outer_radius: s.outer_radius,
            base_facing: s.base_facing,
        });
    }
    Ok(WorldRules { crates, starting_units, time_limit: raw.time_limit })
}

/// Resolve the non-damage warheads of a weapon.
pub(crate) fn resolve_effects(weapon: &str, raw: Vec<RawWarheadEffect>) -> Result<Vec<WarheadEffect>, String> {
    let n = |f: &str| format!("weapons.{}.effects.{f}", truncate(weapon));
    count(&n("list"), raw.len(), 32)?;
    let mut out = Vec::new();
    for e in raw {
        let resources = e.resource_types.iter().fold(0u8, |m, r| {
            m | match r.as_str() {
                "Ore" => RESOURCE_ORE,
                "Gems" => RESOURCE_GEMS,
                _ => 0,
            }
        });
        if e.kind == EffectKind::CreateResource && resources == 0 {
            return Err(n("create_resource names no known resource"));
        }
        out.push(WarheadEffect {
            kind: e.kind,
            delay: e.delay,
            valid: e.valid,
            invalid: e.invalid,
            outer: e.size.first().copied().unwrap_or(0),
            inner: e.size.get(1).copied().unwrap_or(0),
            smudge_types: e.smudge_types.iter().fold(0u8, |m, t| {
                m | match t.as_str() {
                    "Scorch" => SMUDGE_SCORCH,
                    "Crater" => SMUDGE_CRATER,
                    _ => 0,
                }
            }),
            chance: e.chance,
            amount: e.amount,
            resources,
            duration: e.duration,
            intensity: e.intensity,
            multiplier: (e.multiplier.first().copied().unwrap_or(0), e.multiplier.get(1).copied().unwrap_or(0)),
            flash_type: e.flash_type,
        });
    }
    Ok(out)
}

impl Rules {
    /// Semantic checks of the lobby option rules (see `Rules::validate`).
    pub(crate) fn validate_options(&self) -> Result<(), String> {
        let w = &self.world;
        let c = &w.crates;
        within("world.crates.minimum", c.minimum, 0, 64)?;
        within("world.crates.maximum", c.maximum, 0, 255)?;
        within("world.crates.spawn_interval", c.spawn_interval, 1, TIMER)?;
        within("world.crates.initial_delay", c.initial_delay, 0, TIMER)?;
        within("world.crates.water_chance", c.water_chance, 0, 100)?;
        within("world.crates.quantized_facings", c.quantized_facings, 1, 1024)?;
        within("world.crates.cordon", c.cordon, 0, 64 * CELLS)?;
        if c.actors.is_empty() || c.actors.len() != c.shares.len() || c.shares.iter().any(|&s| !(0..=10_000).contains(&s)) {
            return Err("world.crates: one share (0..10000) per crate actor".into());
        }
        for &a in &c.actors {
            if self.actors[a].kind != Kind::Crate {
                return Err("world.crates.actors must be crates".into());
            }
        }
        if let Some(d) = c.delivery_aircraft {
            if self.actors[d].unit.as_ref().and_then(|u| u.aircraft.as_ref()).is_none() {
                return Err("world.crates.delivery_aircraft must be an aircraft".into());
            }
        }
        count("world.starting_units", w.starting_units.len(), 64)?;
        for s in &w.starting_units {
            count("world.starting_units.support_actors", s.support_actors.len(), 32)?;
            within("world.starting_units.inner_radius", s.inner_radius, 0, 16)?;
            within("world.starting_units.outer_radius", s.outer_radius, s.inner_radius, 16)?;
            within("world.starting_units.base_facing", s.base_facing, 0, 1023)?;
            for &a in s.support_actors.iter().chain(s.base_actor.iter()) {
                if self.actors[a].unit.is_none() {
                    return Err("world.starting_units: only units start on the map".into());
                }
            }
        }
        let t = &w.time_limit;
        count("world.time_limit.options", t.options.len(), 32)?;
        if t.options.iter().any(|&m| !(0..=1000).contains(&m)) || !t.options.contains(&t.default) {
            return Err("world.time_limit: options are 0..1000 minutes and include the default".into());
        }
        if t.warnings.len() != t.notifications.len() || t.warnings.iter().any(|&m| !(1..=1000).contains(&m)) {
            return Err("world.time_limit: one notification per warning of 1..1000 minutes".into());
        }
        for a in &self.actors {
            let n = |f: &str| format!("actors.{}.{f}", truncate(&a.id));
            let o = &a.options;
            if let Some(b) = o.gives_bounty {
                within(&n("gives_bounty"), b, 0, 1000)?;
            }
            if let Some(t) = o.spawn_on_death {
                if !matches!(self.actors[t].kind, Kind::Husk | Kind::Crate) {
                    return Err(n("spawn_on_death must be a husk or a crate"));
                }
            }
            if let Some((t, p)) = o.full_husk {
                within(&n("full_husk threshold"), p, 0, 100)?;
                if self.actors[t].kind != Kind::Husk {
                    return Err(n("full_husk must be a husk"));
                }
            }
            if let Some(s) = &o.sell_survivors {
                within(&n("sell_survivors.value_percent"), s.value_percent, 0, 1000)?;
                within(&n("sell_survivors.min_hp_percent"), s.min_hp_percent, 0, 100)?;
                count(&n("sell_survivors.actor_types"), s.actor_types.len(), 64)?;
                count(&n("sell_survivors.guaranteed"), s.guaranteed.len(), 64)?;
                for &t in s.actor_types.iter().chain(&s.guaranteed) {
                    if self.actors[t].unit.is_none() || self.actors[t].kind == Kind::Aircraft {
                        return Err(n("sell_survivors: only ground units leave a sold structure"));
                    }
                }
            }
            if let Some((d, i)) = o.shake_on_death {
                within(&n("shake_on_death duration"), d, 0, TIMER)?;
                within(&n("shake_on_death intensity"), i, 0, 1000)?;
            }
            if (a.kind == Kind::Husk) != o.husk.is_some() || (a.kind == Kind::Crate) != o.crate_info.is_some() {
                return Err(n("husk and crate info belong to husks and crates"));
            }
            if let Some(h) = &o.husk {
                within(&n("husk.burn_delay"), h.burn_delay, 1, TIMER)?;
                within(&n("husk.burn_step"), h.burn_step, -100_000_000, 100_000_000)?;
                within(&n("husk.burn_start_if_below"), h.burn_start_if_below, 0, 1000)?;
                within(&n("husk.radius"), h.radius, 1, 2 * CELLS)?;
                for c in h.capturable.iter().chain(h.infiltrate.iter()) {
                    if self.actors[c.transform_into].unit.is_none() {
                        return Err(n("husk: a husk turns back into a unit"));
                    }
                    within(&n("husk force_health_percent"), c.force_health_percent, 0, 100)?;
                }
            }
            if let Some(c) = &o.crate_info {
                within(&n("crate.duration"), c.duration, 0, TIMER * 10)?;
                for x in &c.actions {
                    let m = |f: &str| n(&format!("crate.actions.{}.{f}", truncate(&x.key)));
                    within(&m("shares"), x.shares, 0, 10_000)?;
                    within(&m("time_delay"), x.time_delay, 0, TIMER * 10)?;
                    within(&m("amount"), x.amount, -1_000_000, 1_000_000)?;
                    within(&m("levels"), x.levels, 0, crate::rules::MAX_LEVELS as i32)?;
                    within(&m("range"), x.range, 0, 16 * CELLS)?;
                    within(&m("max_extra"), x.max_extra, -1, 64)?;
                    within(&m("max_amount"), x.max_amount, 0, 32)?;
                    within(&m("min_amount"), x.min_amount, 0, 32)?;
                    within(&m("max_radius"), x.max_radius, 0, 16)?;
                    within(&m("no_base_shares"), x.no_base_shares, 0, 10_000)?;
                    within(&m("duration"), x.duration, 0, TIMER)?;
                    count(&m("units"), x.units.len(), 32)?;
                    if let Some(w) = x.weapon {
                        if w >= self.weapons.len() {
                            return Err(m("weapon: unknown weapon"));
                        }
                    }
                    if x.kind == CrateActionKind::Explode && x.weapon.is_none() {
                        return Err(m("an explode action needs a weapon"));
                    }
                    for &u in &x.units {
                        if self.actors[u].unit.is_none() {
                            return Err(m("units must be units"));
                        }
                    }
                }
            }
        }
        for w in &self.weapons {
            for e in &w.effects {
                let n = |f: &str| format!("weapons.{}.effects.{f}", truncate(&w.name));
                within(&n("delay"), e.delay, 0, 10_000)?;
                within(&n("size"), e.outer, 0, 16)?;
                within(&n("size"), e.inner, 0, e.outer.max(0))?;
                within(&n("chance"), e.chance, 0, 100)?;
                within(&n("amount"), e.amount, 0, 255)?;
                within(&n("duration"), e.duration, 0, TIMER)?;
                within(&n("intensity"), e.intensity, 0, 1000)?;
            }
        }
        Ok(())
    }
}
